import type { SeedProfile } from './profiles';

const q = (value: string | null): string => (value === null ? 'null' : `'${value.replace(/'/g, "''")}'`);
const arr = (values: readonly string[]): string => q(`{${values.join(',')}}`);

/** Renders the seed as plain SQL, applied by `supabase db reset` (local only). */
export function toSql(profiles: SeedProfile[]): string {
  const out: string[] = [
    '-- GENERATED by supabase/seed (npm run seed:generate). Do not edit by hand.',
    `-- ${profiles.length} fictional profiles, fictional phone numbers, no photos (initials avatars).`,
    '',
  ];

  for (const p of profiles) {
    const sensitive = {
      seeking_genders: p.seekingGenders,
      friend_genders: ['woman', 'man', 'non_binary'],
      orientation: p.orientation,
      orientation_visible: p.orientation ? p.orientationVisible : null,
      situation: p.situation,
      structure: p.structure,
      composition: p.composition && {
        kinds: p.composition.kinds,
        three_plus_genders: p.composition.threePlusGenders,
      },
    };

    out.push(
      `-- ${p.firstName}, ${p.city}`,
      `insert into auth.users (instance_id, id, aud, role, phone, phone_confirmed_at, email, email_confirmed_at, raw_app_meta_data, raw_user_meta_data,`,
      `  created_at, updated_at, confirmation_token, recovery_token, email_change_token_new, email_change,`,
      `  phone_change, phone_change_token, email_change_token_current, reauthentication_token)`,
      `values ('00000000-0000-0000-0000-000000000000', ${q(p.id)}, 'authenticated', 'authenticated', ${q(p.phone)}, now(), ${q(p.email)}, now(),`,
      `  '{"provider":"phone","providers":["phone","email"]}', '{}', now(), now(), '', '', '', '', '', '', '', '');`,
      `insert into auth.identities (provider_id, user_id, identity_data, provider, created_at, updated_at)`,
      `values (${q(p.id)}, ${q(p.id)}, ${q(JSON.stringify({ sub: p.id, phone: p.phone }))}, 'phone', now(), now()),`,
      `  (${q(p.id)}, ${q(p.id)}, ${q(JSON.stringify({ sub: p.id, email: p.email, email_verified: true }))}, 'email', now(), now());`,
      `update public.profiles set first_name = ${q(p.firstName)}, birth_date = ${q(p.birthDate)}, gender = ${q(p.gender)},`,
      `  bio = ${q(p.bio)}, open_to_couples = ${p.openToCouples}, alcohol_free_icons = ${p.alcoholFreeIcons},`,
      `  verification_status = ${p.verified ? "'verified'" : "'pending'"}, verified_at = ${p.verified ? 'now()' : 'null'},`,
      `  location = private.snap_point(${p.lat}, ${p.lon}), location_source = 'device', country_code = 'FR',`,
      `  department_code = ${q(p.departmentCode)}, region_code = ${q(p.regionCode)},`,
      `  last_active_at = now() - interval '${p.lastActiveHoursAgo} hours', is_seed = true, status = 'active'`,
      `where id = ${q(p.id)};`,
      `insert into public.consents (user_id, type, version) values`,
      `  (${q(p.id)}, 'terms', 1), (${q(p.id)}, 'privacy', 1), (${q(p.id)}, 'sensitive_data', 1);`,
      `insert into public.profile_drinks (user_id, drink) select ${q(p.id)}::uuid, unnest(${arr(p.drinks)}::public.drink[]);`,
      `insert into private.drink_change_history (user_id, old_drinks, new_drinks, reason)`,
      `  values (${q(p.id)}, null, ${arr(p.drinks)}, 'seed');`,
      `select private.write_sensitive(${q(p.id)}, ${q(JSON.stringify(sensitive))});`,
      `insert into public.profile_prompts (user_id, position, question_code, answer) values`,
      p.prompts.map((pr, idx) => `  (${q(p.id)}, ${idx + 1}, ${q(pr.questionCode)}, ${q(pr.answer)})`).join(',\n') + ';',
      '',
    );
  }
  return out.join('\n');
}
